const getCompatibleFiles = useCallback(
  (params: TParams, selectedFiles: StirlingFile[]) => {
    const endpoint =
      typeof config.endpoint === "function"
        ? config.endpoint(params)
        : config.endpoint;
    return selectedFiles.filter((file) =>
      toolAcceptsFile(
